import { useEffect, useMemo, useState, type CSSProperties, type ReactNode } from 'react';
import { useMsal } from '@azure/msal-react';
import { api, type ProcessBlueprint } from '../lib/api';

type FieldType = 'text' | 'number' | 'date' | 'textarea' | 'select' | 'checkbox';

type ProposalField = {
 key: string;
 label: string;
 type: FieldType;
 required?: boolean;
};

type ProposalNode = {
 id: string;
 type: 'task' | 'approval' | 'start' | 'end';
 label: string;
 description?: string;
 approver_type?: 'email' | 'requester' | 'role';
 approver_email?: string;
 role?: string;
 form?: { fields: ProposalField[] };
 attachment_rules?: {
  required?: boolean;
  min_files?: number;
  allowed_types?: string[];
  label?: string;
 };
};

type Proposal = {
 process_key: string;
 process_name: string;
 version: number;
 nodes: ProposalNode[];
};

type BuilderBlueprint = ProcessBlueprint & {
 description?: string | null;
 source_text?: string | null;
 proposed_process_json?: string | null;
 status: string;
};

type Tab = 'form' | 'workflow' | 'settings' | 'publish';

type GraphUser = {
  id: string;
  displayName?: string;
  mail?: string;
  userPrincipalName?: string;
  jobTitle?: string;
  department?: string;
};

const GRAPH_SCOPES = ['User.Read.All'];
